<template><span class="emoji-anchor"><button ref="reference" type="button" class="emoji-trigger" :aria-label="label" :aria-expanded="open" @click="open=!open">{{value||'☺'}}</button><div v-if="open" ref="floating" class="emoji-floating" :style="floatingStyles" @keydown.esc.stop.prevent="close"><div ref="host" class="emoji-host"/><p v-if="error">{{error}}</p></div></span></template>
<script setup lang="ts">
import {nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue';import {useFloating,autoUpdate,offset,flip,shift} from '@floating-ui/vue';
withDefaults(defineProps<{value?:string;label?:string}>(),{value:'',label:'Выбрать значок'});const emit=defineEmits<{select:[value:string]}>();
const open=ref(false),error=ref(''),reference=ref<HTMLElement|null>(null),floating=ref<HTMLElement|null>(null),host=ref<HTMLElement|null>(null);let revision=0,owned:HTMLElement|null=null;
const {floatingStyles}=useFloating(reference,floating,{placement:'bottom-start',strategy:'fixed',middleware:[offset(8),flip(),shift({padding:12})],whileElementsMounted:autoUpdate});
function close(){open.value=false;reference.value?.focus();}function outside(e:PointerEvent){const path=e.composedPath();if(open.value&&!path.includes(reference.value!)&&!path.includes(floating.value!))open.value=false;}
watch(open,async value=>{const ticket=++revision;owned?.remove();owned=null;if(!value)return;error.value='';await nextTick();try{const [{Picker},{default:ru}]=await Promise.all([import('emoji-picker-element'),import('emoji-picker-element/i18n/ru_RU')]);if(ticket!==revision||!host.value)return;const picker=new Picker({locale:'ru',dataSource:new URL('/emoji-ru.json',location.href).href,i18n:ru});picker.style.cssText='--background:var(--surface);--border-color:var(--line);--button-hover-background:var(--hover);--input-font-color:var(--fg);--input-font-size:14px;--input-border-color:var(--line);--input-border-radius:6px;--category-font-color:var(--fg-dim);--num-columns:8;--emoji-size:1.25rem;--outline-color:var(--accent);--indicator-color:var(--accent);width:min(340px,calc(100vw - 40px));height:340px';picker.addEventListener('emoji-click',event=>{const value=(event as unknown as CustomEvent<{unicode?:string}>).detail.unicode;if(typeof value==='string'&&value.length<=32){emit('select',value);close();}});owned=picker;host.value.append(picker);}catch{if(ticket===revision)error.value='Не удалось открыть значки';}});
onMounted(()=>document.addEventListener('pointerdown',outside,true));onBeforeUnmount(()=>{revision++;owned?.remove();document.removeEventListener('pointerdown',outside,true);});
</script>
<style scoped>.emoji-anchor{display:inline-flex}.emoji-trigger{display:grid;place-items:center;min-width:32px;min-height:32px;border:1px solid var(--line);border-radius:7px;background:var(--surface);color:var(--fg);font-size:19px;cursor:pointer}.emoji-floating{z-index:10000;max-width:calc(100vw - 24px);border:1px solid var(--line);border-radius:11px;overflow:hidden;box-shadow:0 12px 40px #0004;background:var(--surface);color:var(--fg)}.emoji-floating p{padding:12px;font-size:12px}</style>
